        format_f32(hsv.s),
        format_f32(hsv.v),
        format_f32(cmyk.c),
        format_f32(cmyk.m),
        format_f32(cmyk.y),
        format_f32(cmyk.k),
        format_f32(yuv.y),
        format_f32(yuv.u),
        format_f32(yuv.v),
    );
}

