//! Re-implementation of the ColorSpace C++ header's color types and
//! conversions. Precision mirrors the original: RGB/CMYK/YUV arithmetic is
//! f32, while HSL/HSV are computed in f64 (C++ `double` locals).

#[derive(Debug, Clone, Copy)]
pub struct Rgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

impl Rgb {
    pub fn new(r: f32, g: f32, b: f32) -> Self {
        Rgb { r, g, b }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Hsl {
    pub h: f64,
    pub s: f64,
    pub l: f64,
}

#[derive(Debug, Clone, Copy)]
pub struct Hsv {
    pub h: f64,
    pub s: f64,
    pub v: f64,
}

#[derive(Debug, Clone, Copy)]
pub struct Cmyk {
    pub c: f32,
    pub m: f32,
    pub y: f32,
    pub k: f32,
}

#[derive(Debug, Clone, Copy)]
pub struct Yuv {
    pub y: f32,
    pub u: f32,
    pub v: f32,
}

pub struct ColorConverter;

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: &Rgb) -> Hsl {
        let r = rgb.r as f64;
        let g = rgb.g as f64;
        let b = rgb.b as f64;
        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let d = max - min;

        let l = (max + min) / 2.0;

        let (mut h, mut s) = (0.0f64, 0.0f64);
        if d != 0.0 {
            s = d / (1.0 - (2.0 * l - 1.0).abs());
            if max == r {
                h = 60.0 * (((g - b) / d) % 6.0);
            } else if max == g {
                h = 60.0 * ((b - r) / d + 2.0);
            } else {
                h = 60.0 * ((r - g) / d + 4.0);
            }
        }
        if h < 0.0 {
            h += 360.0;
        }
        Hsl { h, s, l }
    }

    pub fn rgb_to_hsv(rgb: &Rgb) -> Hsv {
        let r = rgb.r as f64;
        let g = rgb.g as f64;
        let b = rgb.b as f64;
        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let d = max - min;

        let v = max;

        let (mut h, mut s) = (0.0f64, 0.0f64);
        if max != 0.0 {
            s = d / max;
        }
        if d != 0.0 {
            if max == r {
                h = 60.0 * (((g - b) / d) % 6.0);
            } else if max == g {
                h = 60.0 * ((b - r) / d + 2.0);
            } else {
                h = 60.0 * ((r - g) / d + 4.0);
            }
        }
        if h < 0.0 {
            h += 360.0;
        }
        Hsv { h, s, v }
    }

    pub fn rgb_to_cmyk(rgb: &Rgb) -> Cmyk {
        let k = 1.0 - rgb.r.max(rgb.g).max(rgb.b);
        if k == 1.0 {
            return Cmyk {
                c: 0.0,
                m: 0.0,
                y: 0.0,
                k,
            };
        }
        let d = 1.0 - k;
        Cmyk {
            c: (1.0 - rgb.r - k) / d,
            m: (1.0 - rgb.g - k) / d,
            y: (1.0 - rgb.b - k) / d,
            k,
        }
    }

    pub fn rgb_to_yuv(rgb: &Rgb) -> Yuv {
        Yuv {
            y: 0.299f32 * rgb.r + 0.587f32 * rgb.g + 0.114f32 * rgb.b,
            u: -0.147f32 * rgb.r - 0.289f32 * rgb.g + 0.436f32 * rgb.b,
            v: 0.615f32 * rgb.r - 0.515f32 * rgb.g - 0.1f32 * rgb.b,
        }
    }
}

