use std::fs;

// %g formatting (6 sig digits) of f64 value
fn g64(value: f64) -> String {
    if value.is_nan() {
        return "nan".into();
    }
    if value.is_infinite() {
        return if value < 0.0 { "-inf" } else { "inf" }.into();
    }
    let negative = value.is_sign_negative();
    let abs = if negative { -value } else { value };
    let body = if abs == 0.0 { "0".to_string() } else { pos(abs) };
    if negative { format!("-{}", body) } else { body }
}
fn g32(v: f32) -> String {
    g64(v as f64)
}
fn pos(x: f64) -> String {
    let sci = format!("{:.5e}", x);
    let (mantissa, exp_str) = sci.split_once('e').unwrap();
    let exp: i32 = exp_str.parse().unwrap();
    let digits: String = mantissa.chars().filter(|c| c.is_ascii_digit()).collect();
    if exp < -4 || exp >= 6 {
        let mut m: String = digits.trim_end_matches('0').to_string();
        if m.len() > 1 {
            m.insert(1, '.');
        }
        let sign = if exp < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", m, sign, exp.abs())
    } else if exp >= 0 {
        let int_len = (exp + 1) as usize;
        let frac: &str = digits[int_len..].trim_end_matches('0');
        if frac.is_empty() {
            digits[..int_len].to_string()
        } else {
            format!("{}.{}", &digits[..int_len], frac)
        }
    } else {
        let zeros = (-exp - 1) as usize;
        let frac: &str = digits.trim_end_matches('0');
        format!("0.{}{}", "0".repeat(zeros), frac)
    }
}

fn main() {
    let data = fs::read_to_string("/tmp/corpus.txt").unwrap();
    // mismatch counters
    let mut names: Vec<String> = Vec::new();
    let mut counts: Vec<usize> = Vec::new();
    let mut register = |names: &mut Vec<String>, counts: &mut Vec<usize>, name: &str| {
        names.push(name.to_string());
        counts.push(0);
    };
    // fields: hsl.h hsl.s hsl.l hsv.h hsv.s
    let l_models = ["L_A_f64", "L_B_f64", "L_A_f32cast", "L_B_f32cast"];
    let s_models = ["S1", "S2", "S3", "S4", "S5", "S2c", "S4c"];
    let h_models = ["H1", "H2", "H3", "H4", "H5", "H1c", "H2c", "H5c"];
    let v_models = ["V1", "V2", "V3", "V4", "V1c", "V2c"];
    for n in l_models.iter().map(|s| format!("l.{}", s)) {
        register(&mut names, &mut counts, &n);
    }
    for n in s_models.iter().map(|s| format!("s.{}", s)) {
        register(&mut names, &mut counts, &n);
    }
    for n in h_models.iter().map(|s| format!("h.{}", s)) {
        register(&mut names, &mut counts, &n);
    }
    for n in v_models.iter().map(|s| format!("v.{}", s)) {
        register(&mut names, &mut counts, &n);
    }
    // hue appears twice (hsl.h and hsv.h identical in ref); count separately
    let mut h2counts = vec![0usize; h_models.len()];

    for line in data.lines() {
        let parts: Vec<&str> = line.split(" | ").collect();
        let inp: Vec<f32> = parts[0].split_whitespace().map(|s| s.parse().unwrap()).collect();
        let toks: Vec<&str> = parts[1].split_whitespace().collect();
        let (r, g, b) = (inp[0], inp[1], inp[2]);
        let max32 = r.max(g).max(b);
        let min32 = r.min(g).min(b);
        let d32 = max32 - min32;
        let sum32 = max32 + min32;
        let (max64, min64) = (max32 as f64, min32 as f64);
        let d64 = max64 - min64;
        let sum64 = max64 + min64;

        // ---- l models ----
        let l_a = sum64 / 2.0;
        let l_b = (sum32 as f64) / 2.0;
        let l_vals = [
            g64(l_a),
            g64(l_b),
            g32(l_a as f32),
            g32(l_b as f32),
        ];
        for (i, v) in l_vals.iter().enumerate() {
            if v != toks[2] {
                counts[i] += 1;
            }
        }

        // ---- s models (hsl.s) ----
        let l32 = sum32 / 2.0; // f32
        let l64a = sum64 / 2.0;
        let l64b = (sum32 as f64) / 2.0;
        let mut s_vals: Vec<String> = Vec::new();
        let compute = |f: &dyn Fn() -> f64| -> f64 {
            if d32 != 0.0 {
                f()
            } else {
                0.0
            }
        };
        // S1: full f64 from f32 inputs, F1 formula
        s_vals.push(g64(compute(&|| d64 / (1.0 - (2.0 * l64a - 1.0).abs()))));
        // S2: rounded d32 & sum32, f64 division, F1
        s_vals.push(g64(compute(&|| {
            (d32 as f64) / (1.0 - (2.0 * l64b - 1.0).abs())
        })));
        // S3: all f32, F1
        s_vals.push(g32(if d32 != 0.0 {
            d32 / (1.0 - (2.0 * l32 - 1.0).abs())
        } else {
            0.0
        }));
        // S4: rounded intermediates, f64, branch formula
        s_vals.push(g64(compute(&|| {
            if l64b < 0.5 {
                (d32 as f64) / (sum32 as f64)
            } else {
                (d32 as f64) / (2.0 - sum32 as f64)
            }
        })));
        // S5: all f32 branch
        s_vals.push(g32(if d32 != 0.0 {
            if l32 < 0.5 {
                d32 / sum32
            } else {
                d32 / (2.0 - sum32)
            }
        } else {
            0.0
        }));
        // S2c: S2 cast to f32
        s_vals.push(g32(if d32 != 0.0 {
            ((d32 as f64) / (1.0 - (2.0 * l64b - 1.0).abs())) as f32
        } else {
            0.0
        }));
        // S4c: S4 cast to f32
        s_vals.push(g32(if d32 != 0.0 {
            (if l64b < 0.5 {
                (d32 as f64) / (sum32 as f64)
            } else {
                (d32 as f64) / (2.0 - sum32 as f64)
            }) as f32
        } else {
            0.0
        }));
        let off = 4; // l models count
        for (i, v) in s_vals.iter().enumerate() {
            if v != toks[1] {
                counts[off + i] += 1;
            }
        }

        // ---- hue models ----
        // numerator per branch
        let branch = if max32 == min32 {
            0
        } else if max32 == r {
            1
        } else if max32 == g {
            2
        } else {
            3
        };
        let num32 = match branch {
            1 => g - b,
            2 => b - r,
            3 => r - g,
            _ => 0.0,
        };
        let num64 = match branch {
            1 => g as f64 - b as f64,
            2 => b as f64 - r as f64,
            3 => r as f64 - g as f64,
            _ => 0.0,
        };
        let fixup = |mut h: f64| {
            if h < 0.0 {
                h += 360.0;
            }
            h
        };
        let fixup32 = |mut h: f32| {
            if h < 0.0 {
                h += 360.0;
            }
            h
        };
        let mut h_vals: Vec<String> = Vec::new();
        // H1: full f64
        h_vals.push(g64(if branch == 0 {
            0.0
        } else {
            let q = num64 / d64;
            fixup(match branch {
                1 => 60.0 * (q % 6.0),
                2 => 60.0 * (q + 2.0),
                _ => 60.0 * (q + 4.0),
            })
        }));
        // H2: f32 numerator & division, f64 fmod/scale
        let q32 = num32 / d32;
        h_vals.push(g64(if branch == 0 {
            0.0
        } else {
            let q = q32 as f64;
            fixup(match branch {
                1 => 60.0 * (q % 6.0),
                2 => 60.0 * (q + 2.0),
                _ => 60.0 * (q + 4.0),
            })
        }));
        // H3: all f32
        h_vals.push(g32(if branch == 0 {
            0.0
        } else {
            fixup32(match branch {
                1 => 60.0 * (q32 % 6.0),
                2 => 60.0 * (q32 + 2.0),
                _ => 60.0 * (q32 + 4.0),
            })
        }));
        // H4: f32 division, f32 fmod/offset, f64 scale
        h_vals.push(g64(if branch == 0 {
            0.0
        } else {
            let t = match branch {
                1 => q32 % 6.0,
                2 => q32 + 2.0,
                _ => q32 + 4.0,
            };
            fixup(60.0 * (t as f64))
        }));
        // H5: f64 numerator over d32, f64 rest
        h_vals.push(g64(if branch == 0 {
            0.0
        } else {
            let q = num64 / (d32 as f64);
            fixup(match branch {
                1 => 60.0 * (q % 6.0),
                2 => 60.0 * (q + 2.0),
                _ => 60.0 * (q + 4.0),
            })
        }));
        // H1c: H1 cast f32
        h_vals.push(g32(if branch == 0 {
            0.0
        } else {
            let q = num64 / d64;
            fixup(match branch {
                1 => 60.0 * (q % 6.0),
                2 => 60.0 * (q + 2.0),
                _ => 60.0 * (q + 4.0),
            }) as f32
        }));
        // H2c: H2 cast f32
        h_vals.push(g32(if branch == 0 {
            0.0
        } else {
            let q = q32 as f64;
            fixup(match branch {
                1 => 60.0 * (q % 6.0),
                2 => 60.0 * (q + 2.0),
                _ => 60.0 * (q + 4.0),
            }) as f32
        }));
        // H5c: H5 cast f32
        h_vals.push(g32(if branch == 0 {
            0.0
